      "Тогда учитель решил проверить, знает ли Филипок буквы, и спросил, умеет ли он сложить своё имя.",
      "Филипок бойко назвал все буквы своего имени и даже сложил из них слово, ни разу не ошибившись.",
      "Учитель удивился и похвалил его: «Молодец! Вижу, что учиться тебе хочется. Скажи матери, пусть присылает тебя в школу».",
      "Филипок был так счастлив, что весь урок просидел тихо, а после школы бежал домой и всем встречным хвастался, что теперь он тоже ученик.",
