      "Тонкий же только что вышел из вагона и был навьючен чемоданами, узлами и картонками. Пахло от него ветчиной.",
      "«Порфирий! — воскликнул толстый. — Ты ли это? Голубчик мой! Сколько лет, сколько зим!»",
      "«Батюшки! — изумился тонкий. — Миша! Друг детства! Откуда ты взялся?»",
      "Приятели трижды расцеловались и посмотрели друг на друга глазами, полными слёз.",
      "«Милый мой! Вот не ожидал! Вот сюрприз! Ну, что же ты? Богат? Женат?» — начал тонкий.",
