      "«Служу, милый мой! Второй год как коллежским асессором. Жалованье плохое, но жена даёт уроки музыки», — рассказывал тонкий.",
      "«Ну а ты как? Небось, уже статский?» — спросил тонкий с надеждой.",
      "«Нет, милый мой, поднимай повыше, — сказал толстый. — Я уже до тайного советника дослужился. Две звезды имею».",
      "Тонкий вдруг побледнел и окаменел, но потом его лицо искривилось в широчайшую улыбку, будто из глаз посыпались искры.",
