      "El flaco, en cambio, acababa de bajar del vagón y venía cargado de maletas, bultos y sombrereras. Olía a jamón.",
      "«¡Porfiri! —exclamó el gordo—. ¿Eres tú? ¡Amigo mío! ¡Cuánto tiempo sin vernos!»",
