      "Los amigos se besaron tres veces y se miraron con los ojos llenos de lágrimas.",
      "«¡Querido mío! ¡No lo esperaba! ¡Qué sorpresa! Bueno, ¿y tú qué? ¿Rico? ¿Casado?» —empezó el flaco.",
