      "El desconocido le preguntó con calma qué pena lo hacía reflexionar tanto en una noche de fiesta, y Mertsalov, para su propia sorpresa, le contó todo.",
      "El anciano escuchó con atención, sin interrumpir, y cuando el relato terminó, se levantó con decisión y dijo: «Vamos ahora mismo a su casa. Soy médico».",
      "Mertsalov, sin atreverse a creer en su suerte, lo guió a través de toda la ciudad hasta su sótano, temiendo todo el camino que aquella suerte se desvaneciera como un sueño.",
      "Al llegar, el médico, sin quitarse el abrigo, fue directo a la cama de la niña enferma, le tocó la frente y le hizo a la madre unas breves preguntas.",
