      "El perrito metió la cola entre las patas y se apretó contra un rincón de la jaula. El león se acercó y lo olfateó.",
      "El perrito se echó de espaldas, levantó las patitas y movió la cola.",
      "El león lo tocó con la pata y lo dio vuelta. El perrito se paró frente a él sobre las patas traseras y se puso a jugar.",
      "El león lo miraba, giraba la cabeza de un lado a otro, y no le hacía daño.",
      "Cuando el dueño le arrojó carne al león, este dejó un pedazo para el perrito.",
      "Por la noche, cuando el león se acostó a dormir, el perrito se acostó a su lado y puso la cabeza sobre su pata.",
      "Desde entonces el perrito vivió en la misma jaula que el león, y el león no le hacía daño, comía con él, dormía con él y jugaba con él.",
      "Un día un señor llegó al zoológico y reconoció a su perrito. Dijo que el perrito era suyo y pidió que se lo devolvieran.",
      "El dueño del zoológico quiso devolver el perrito, pero el león rugió de tal manera que nadie se atrevió a entrar a la jaula.",
      "Durante todo un año el perrito vivió junto al león en la misma jaula. Al año, el perrito enfermó y murió.",
      "El león dejó de comer, solo olfateaba y lamía al perrito, y lo tocaba con la pata.",
      "Cuando comprendió que había muerto, de pronto se levantó de un salto, se erizó, empezó a golpearse los costados con la cola, se lanzó contra la pared de la jaula y se puso a morder los cerrojos y el piso.",
      "Todo el día se agitó, dio vueltas por la jaula y rugió, luego se echó junto al perrito muerto y se quedó quieto.",
      "El dueño quiso llevarse al perrito muerto, pensando que el león se calmaría, pero el león no dejaba que nadie se le acercara.",
