      "Nikolái Almázov, un joven oficial, se preparaba para un examen difícil en la academia militar: el trazado de un mapa topográfico del terreno.",
      "En casa, su joven esposa Vérochka lo ayudaba a prepararse, ahorrando en todo para que él pudiera estudiar tranquilo.",
      "Durante el examen, Almázov, nervioso, dejó caer una gran mancha de tinta sobre el mapa justo en el lugar donde debía trazar la pendiente uniforme de una colina.",
      "Sin perder la calma, dibujó rápidamente sobre la mancha unos arbustos pequeños, como si allí creciera un grupo de matorrales que simplemente había olvidado marcar antes.",
      "El profesor que tomaba el examen revisó el mapa con ojo crítico y afirmó que jamás había habido arbustos en esa zona — él mismo había levantado ese terreno en un mapa años atrás.",
      "Almázov insistió en que los arbustos sí estaban allí de verdad, pero el profesor le puso una calificación reprobatoria y fijó un reexamen para el día siguiente.",
      "Angustiado, Almázov volvió a casa y le contó a su esposa su fracaso: si reprobaba el examen otra vez, su carrera de oficial se acabaría.",
      "Vérochka escuchó a su esposo y, en lugar de desesperarse, se puso a pensar rápidamente cómo salvar la situación.",
      "«Si dibujaste arbustos, entonces deben crecer arbustos de verdad allí — ¡hoy mismo, antes del amanecer!», dijo con decisión.",
      "Propuso comprar arbustos de lilas de verdad y plantarlos exactamente donde Almázov los había dibujado en el mapa, para que el profesor, al ir a verificar el terreno, viera los arbustos con sus propios ojos.",
      "La pareja no tenía dinero para los arbustos ni para los obreros, y Vérochka, sin dudarlo, empeñó sus únicas joyas, regalos de bodas.",
      "Contrataron un cochero, compraron varios arbustos de lilas en un vivero y fueron al lugar señalado en el mapa.",
      "Toda la noche, Almázov, junto con los obreros contratados, cavó hoyos y plantó los arbustos de lilas exactamente en el lugar donde en el mapa había estado la mancha de tinta.",
      "Vérochka misma sostenía el farol y ayudaba a su esposo, helada y agotada, pero decidida a llevar el plan hasta el final.",
      "Al amanecer, cuando ya clareaba, todos los arbustos estaban plantados, y la tierra alrededor cuidadosamente apisonada, como si hubieran crecido allí desde hacía mucho.",
