      "Un día el cartero trajo un sobre escrito con una letra temblorosa y desconocida, y dentro había una carta de un abogado: el padre de Serguéi había fallecido en un asilo de ancianos y le había dejado una única cosa: una vieja libreta de apuntes.",
      "Serguéi quiso tirar la libreta sin leerla, pero algo, tal vez simple curiosidad, lo hizo abrir la primera página.",
      "Allí no había anotaciones de trabajo, sino breves notas, casi diarias, que empezaban justo el día en que su padre se había ido de casa.",
      "«Hoy Seryozha cumplió diez años. Quise llamar, pero no tuve el valor», decía una de las primeras entradas.",
      "Después venían los años, marcados por las fechas de los cumpleaños de sus hijos, sus graduaciones, sus bodas, de las que su padre se enteraba de lejos, por parientes lejanos, y a las que nunca se atrevió a presentarse.",
      "En las últimas páginas, ya escritas con una letra temblorosa de anciano, el padre escribía que la vergüenza había resultado más fuerte que el amor, y que esa vergüenza, acumulada durante años, terminó por quitarle la única vida que valía la pena vivir: la vida junto a sus hijos.",
      "La última anotación era breve: «Espero que algún día me perdonen, aunque yo no llegue a ver ese día. Los quise cada día, solo que nunca supe demostrarlo, y después fue demasiado vergonzoso y demasiado tarde».",
      "Serguéi pasó toda la noche con esa libreta, y al amanecer comprendió que había cargado con rencor hacia un hombre que, resultaba, había sufrido por su propia partida tanto como había sufrido la familia abandonada.",
      "Ya no podía abrazar a su padre ni escuchar esas palabras en voz alta, pero decidió no repetir su error principal: el silencio por orgullo y vergüenza.",
