      "El primer día de la temporada de pesca, todos los botes salieron al mar al mismo tiempo, y Kuzmá, de pie en el muelle, se permitió sonreír por primera vez en todo el largo invierno.",
      "La moraleja de esta historia es la siguiente: la verdadera fuerza de una comunidad no se muestra en la ausencia de tormentas, sino en la dignidad y la unidad con que las personas reconstruyen la vida después de ellas.",
