      "En la víspera de Navidad, en el pueblo ucraniano de Dikanka, el diablo, queriendo vengarse del herrero e iconógrafo local Vakula, que lo había retratado de forma poco favorecedora para pintar la iglesia, roba la luna del cielo y sume al pueblo en la oscuridad.",
