      "Desde entonces, Maxim recordaba aquellos años solo con amargura, considerando al entrenador un hombre sin corazón, para quien los segundos del cronómetro significaban más que los sentimientos de un adolescente que se esforzaba al límite de sus fuerzas.",
      "Ya convertido en un hombre adulto, atravesando un momento difícil tras perder su trabajo, Maxim se enteró por casualidad de que Nikolái Petróvich seguía entrenando a niños en la misma piscina, y decidió por fin decirle todo lo que había acumulado durante tantos años.",
      "Llegó por la tarde, cuando la piscina estaba vacía, y encontró al entrenador solo junto al agua, visiblemente envejecido, pero con la misma mirada directa e imperturbable que Maxim recordaba de su infancia.",
